import type { TopicAuthoringDraft, TopicSeed } from "@zoeskoul/curriculum-contracts";

function normalizeRole(value: unknown): string {
    return String(value ?? "").trim().toLowerCase();
}

export function isProjectLikeTopic(args: {
    seed?: TopicSeed;
    draft?: TopicAuthoringDraft;
}): boolean {
    const seed = args.seed;
    const record = seed as
        | (TopicSeed & {
              topicType?: unknown;
              projectType?: unknown;
              sectionId?: unknown;
          })
        | undefined;
    const topicId = normalizeRole(seed?.topicId);
    const sectionId = normalizeRole(record?.sectionId ?? seed?.sectionSlug);
    const topicType = normalizeRole(record?.topicType);
    const projectType = normalizeRole(record?.projectType);
    const sectionRole = normalizeRole(seed?.sectionRole);
    const moduleRole = normalizeRole(seed?.moduleRole);
    const hasProjectSteps =
        Array.isArray(args.draft?.projectDraft?.stepIds) &&
        args.draft.projectDraft.stepIds.length > 0;

    return (
        topicType === "project" ||
        topicType === "module_project" ||
        topicType === "capstone" ||
        projectType === "module_project" ||
        projectType === "capstone" ||
        sectionRole === "module_project" ||
        sectionRole === "capstone" ||
        moduleRole === "capstone" ||
        Boolean(seed?.projectBrief) ||
        hasProjectSteps ||
        topicId.includes("project") ||
        topicId.includes("capstone") ||
        sectionId.includes("project") ||
        sectionId.includes("capstone")
    );
}

export function messageTag(messageBase: string, field: string): string {
    return `@:${messageBase}.${field}`;
}

function normalizeMessageKeySegment(value: string) {
    return String(value ?? "")
        .trim()
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "_")
        .replace(/^_+|_+$/g, "");
}

export function fileContentMessageField(args: {
    group: "starterFiles" | "solutionFiles" | "files" | "fixtureFiles";
    filePath: string | undefined;
    index: number;
}): string {
    const normalizedPath = normalizeMessageKeySegment(args.filePath ?? "");
    const fileKey = normalizedPath || `file_${args.index + 1}`;
    return `${args.group}.${fileKey}.content`;
}

export function fileContentMessageTag(args: {
    messageBase: string;
    group: "starterFiles" | "solutionFiles" | "files" | "fixtureFiles";
    filePath?: string;
    index: number;
}): string {
    return messageTag(
        args.messageBase,
        fileContentMessageField({
            group: args.group,
            filePath: args.filePath,
            index: args.index,
        }),
    );
}

export function starterFileContentMessageField(
    filePath: string | undefined,
    index: number,
): string {
    return fileContentMessageField({
        group: "starterFiles",
        filePath,
        index,
    });
}

export function starterFileContentMessageTag(args: {
    messageBase: string;
    filePath?: string;
    index: number;
}): string {
    return fileContentMessageTag({
