function formatSqlContext(args: {
    subjectSlug: string;
    courseSlug?: string;
    topicId: string;
    datasetId?: string;
}) {
    const parts = [
        `subject "${args.subjectSlug}"`,
        args.courseSlug ? `course "${args.courseSlug}"` : null,
        `topic "${args.topicId}"`,
        args.datasetId ? `dataset "${args.datasetId}"` : null,
