export function stripSqlComments(sql: string): string {
    return String(sql ?? "")
        .replace(/--.*$/gm, " ")
        .replace(/\/\*[\s\S]*?\*\//g, " ");
}

export function stripSqlStringLiterals(sql: string): string {
    return String(sql ?? "")
        .replace(/'([^']|'')*'/g, " ")
        .replace(/"([^"]|"")*"/g, " ");
}

export function stripSqlCommentsAndStrings(sql: string): string {
    return stripSqlStringLiterals(stripSqlComments(sql));
}

export function findMatchingParen(sql: string, openIndex: number): number {
    let depth = 0;
    let quote: "'" | '"' | "`" | null = null;
    let bracket = false;

    for (let i = openIndex; i < sql.length; i += 1) {
        const ch = sql[i];
        const prev = sql[i - 1];

        if (quote) {
            if (ch === quote && prev !== "\\") quote = null;
            continue;
        }

        if (bracket) {
            if (ch === "]") bracket = false;
            continue;
        }

        if (ch === "'" || ch === '"' || ch === "`") {
            quote = ch;
            continue;
        }

        if (ch === "[") {
            bracket = true;
            continue;
        }

        if (ch === "(") depth += 1;

        if (ch === ")") {
            depth -= 1;
            if (depth === 0) return i;
        }
    }

    return -1;
}

export function findStatementEnd(sql: string, fromIndex: number): number {
    let quote: "'" | '"' | "`" | null = null;
    let bracket = false;

    for (let i = fromIndex; i < sql.length; i += 1) {
        const ch = sql[i];
        const prev = sql[i - 1];

        if (quote) {
            if (ch === quote && prev !== "\\") quote = null;
            continue;
        }

        if (bracket) {
            if (ch === "]") bracket = false;
            continue;
        }

        if (ch === "'" || ch === '"' || ch === "`") {
            quote = ch;
            continue;
        }

        if (ch === "[") {
            bracket = true;
            continue;
        }

        if (ch === ";") return i + 1;
    }

    return sql.length;
}

