        case "java":
            return ".java";
        case "javascript":
            return ".js";
        case "r":
            return ".R";
        case "typescript":
            return ".ts";
        case "c":
            return ".c";
        case "cpp":
            return ".cpp";
        case "bash":
            return ".sh";
        case "sql":
            return ".sql";
        case "web":
            return ".html";
        default:
            return ".txt";
    }
}

export function defaultMainFile(lang: WorkspaceLanguage): string {
