export function normalizeLanguageNarrationSequence(
    items:
        ReadonlyArray<
            LanguageNarrationSequenceItem
        >,
) {
    return items
        .map((item) => ({
            text:
                String(
                    item.text ?? "",
                ).trim(),
            opts:
                item.opts ?? {},
            pauseMs:
                Math.max(
                    0,
                    Math.min(
                        5000,
                        Number(
                            item.pauseMs ??
                                0,
                        ),
                    ),
                ),
        }))
        .filter(
            (item) =>
                item.text.length > 0,
        );
}

export function buildLanguageAudioNarrationSequence(
    audio: LanguageAudioSpec,
): LanguageNarrationSequenceItem[] {
    return audio.segments.map(
        (segment, index) => {
            const turn =
                resolveLanguageAudioTurn(
                    audio,
                    segment,
                );

            return {
                text:
                    turn.text,
                opts:
                    turn.options,
                pauseMs:
                    resolveLanguageAudioPauseMs(
                        audio,
                        segment,
                        index,
                    ),
            };
        },
    );
}

