export function useModuleNav(args: {
    subjectSlug: string;
    moduleSlug: string;
    catalogSlug?: string | null;
    enabled?: boolean;
}) {
    const {
        subjectSlug,
        moduleSlug,
        catalogSlug = null,
        enabled = true,
    } = args;
    const [nav, setNav] = useState<ModuleNavInfo | undefined>(
        enabled ? undefined : null,
    );

    useEffect(() => {
        if (!enabled) {
            setNav(null);
            return;
        }
        if (!subjectSlug || !moduleSlug) return;
        setNav(undefined);

        const ctrl = new AbortController();
        const search = new URLSearchParams({
            subjectSlug,
            moduleSlug,
        });

        if (catalogSlug) {
            search.set("catalogSlug", catalogSlug);
        }

        fetch(`/api/review/module-nav?${search.toString()}`, {
            cache: "no-store",
            signal: ctrl.signal,
        })
            .then((r) => (r.ok ? r.json() : null))
            .then((d) => setNav(d))
            .catch((e) => {
                if (e?.name !== "AbortError") setNav(null);
            });

        return () => ctrl.abort();
    }, [catalogSlug, enabled, subjectSlug, moduleSlug]);

    return nav;
}

