  locales: readonly string[];
  defaultLocale: string;
};

type QueryScalar =
  | string
  | number
  | boolean
  | null
  | undefined;

type QueryValue =
  | QueryScalar
  | readonly QueryScalar[];

export type NavigationHref =
  | string
  | {
      pathname: string;
      query?: Record<string, QueryValue>;
      hash?: string;
    };

type LinkProps = Omit<
  AnchorHTMLAttributes<HTMLAnchorElement>,
  "href"
> & {
  href: NavigationHref;
  locale?: string;
  prefetch?: boolean;
};

function hrefToString(href: NavigationHref): string {
  if (typeof href === "string") {
    return href;
  }

  const params = new URLSearchParams();

  for (const [key, value] of Object.entries(
    href.query ?? {},
  )) {
    const values = Array.isArray(value)
      ? value
      : [value];

    for (const entry of values) {
      if (entry == null) {
        continue;
      }

      params.append(key, String(entry));
    }
  }

  const search = params.toString();
  const hash = href.hash
    ? href.hash.startsWith("#")
      ? href.hash
      : `#${href.hash}`
    : "";

  return `${href.pathname}${
    search ? `?${search}` : ""
  }${hash}`;
}

function isPlainPrimaryClick(
  event: MouseEvent<HTMLAnchorElement>,
) {
  return (
    !event.defaultPrevented &&
    event.button === 0 &&
    !event.metaKey &&
    !event.ctrlKey &&
    !event.shiftKey &&
    !event.altKey
  );
}

function resolveHref(
  href: NavigationHref,
  locale?: string,
) {
  const value = hrefToString(href);
  const selectedLocale =
    locale ?? currentLocale();
  const websiteOrigin =
    import.meta.env.VITE_WEBSITE_ORIGIN ??
    "http://localhost:3000";
  const websiteHref =
    externalWebsiteHref({
      rawHref: value,
      locale: selectedLocale,
      websiteOrigin,
    });

  if (websiteHref) {
    return websiteHref;
  }

  return value.startsWith("#")
    ? value
    : localizedHref(
        value,
        selectedLocale,
      );
}

export function createNavigation(
  _routing: RoutingConfig,
) {
  const Link = forwardRef<
    HTMLAnchorElement,
    LinkProps
  >(function Link(
    {
      href,
