import { useSyncExternalStore } from "react";

const NAVIGATION_EVENT = "zoeskoul:vite-navigation";

function snapshot() {
  return `${window.location.pathname}${window.location.search}${window.location.hash}`;
}

function serverSnapshot() {
  return "/";
}

function subscribe(listener: () => void) {
  window.addEventListener("popstate", listener);
  window.addEventListener(NAVIGATION_EVENT, listener);
  return () => {
    window.removeEventListener("popstate", listener);
    window.removeEventListener(NAVIGATION_EVENT, listener);
  };
}

export function useLocationSnapshot() {
  return useSyncExternalStore(subscribe, snapshot, serverSnapshot);
}

export function emitNavigation() {
  window.dispatchEvent(new Event(NAVIGATION_EVENT));
}

export function publishNavigation(
  href: string,
  options: {
    replace?: boolean;
    state?: unknown;
    scroll?: boolean;
  } = {},
) {
  const state = options.state ?? {};

  if (options.replace) {
    window.history.replaceState(state, "", href);
  } else {
    window.history.pushState(state, "", href);
  }

  emitNavigation();

  if (options.scroll !== false) {
    window.scrollTo({ top: 0, left: 0 });
  }
}

export function navigate(
  href: string,
  options: {
    replace?: boolean;
    locale?: string;
    scroll?: boolean;
  } = {},
) {
  const current = new URL(window.location.href);
  const target = new URL(href, current);

  if (options.locale) {
    const segments = target.pathname.split("/").filter(Boolean);
    if (/^(en|es|fr|ht)$/.test(segments[0] ?? "")) {
      segments[0] = options.locale;
    } else {
      segments.unshift(options.locale);
    }
    target.pathname = `/${segments.join("/")}`;
  }

  const next = `${target.pathname}${target.search}${target.hash}`;

  publishNavigation(next, options);
}

export function currentLocale() {
  const first = window.location.pathname.split("/").filter(Boolean)[0];
  return /^(en|es|fr|ht)$/.test(first ?? "") ? first : "en";
}

export function stripLocale(pathname: string) {
  const segments = pathname.split("/").filter(Boolean);
  if (/^(en|es|fr|ht)$/.test(segments[0] ?? "")) {
    segments.shift();
  }

  return segments.length
    ? `/${segments.join("/")}`
    : "/";
}

export function localizedHref(href: string, locale = currentLocale()) {
  if (
    !href.startsWith("/") ||
    href.startsWith("/api/") ||
    href.startsWith("//")
  ) {
    return href;
  }

  const url = new URL(href, window.location.origin);
  const segments = url.pathname.split("/").filter(Boolean);

  if (/^(en|es|fr|ht)$/.test(segments[0] ?? "")) {
    segments[0] = locale;
  } else {
    segments.unshift(locale);
  }

  url.pathname = `/${segments.join("/")}`;
  return `${url.pathname}${url.search}${url.hash}`;
}

export const VITE_REFRESH_EVENT =
  "zoeskoul:vite-refresh";

export function refreshClientData() {
  if (typeof window === "undefined") {
    return;
  }

  window.dispatchEvent(
    new Event(VITE_REFRESH_EVENT),
  );
}

import {
  useEffect,
  useState,
  type ReactNode,
} from "react";
import {
  useAppPreferences,
} from "@zoeskoul/preferences/react";
import type {
  I18nMessages,
} from "@zoeskoul/i18n-core";

import {
  IntlBridgeProvider,
} from "../compat/next-intl";
import {
  currentLocale,
  navigate,
  useLocationSnapshot,
} from "../compat/navigation-runtime";
import {
  loadTeacherLocaleMessages,
} from "./messages";

export function TeacherIntlProvider(props: {
  children: ReactNode;
}) {
  const { preferences } =
    useAppPreferences();
  const location =
    useLocationSnapshot();
  const routeLocale =
    currentLocale();
  const routeMatchesPreference =
    routeLocale === preferences.locale;

  const [state, setState] = useState<{
    locale: string;
    messages: I18nMessages;
  } | null>(null);

  useEffect(() => {
    if (routeMatchesPreference) {
      return;
    }

    navigate(location, {
      replace: true,
      locale: preferences.locale,
      scroll: false,
    });
  }, [
    location,
    preferences.locale,
    routeMatchesPreference,
  ]);

  useEffect(() => {
    if (!routeMatchesPreference) {
      return;
    }

    let cancelled = false;

    void loadTeacherLocaleMessages(
      routeLocale,
    )
      .then((messages) => {
        if (!cancelled) {
          setState({
            locale: routeLocale,
            messages,
          });
        }
      })
      .catch((error) => {
        console.error(
          "[teacher i18n] locale messages",
          error,
        );

        if (!cancelled) {
          setState({
            locale: routeLocale,
            messages: {},
          });
        }
      });

    return () => {
      cancelled = true;
    };
  }, [
    routeLocale,
    routeMatchesPreference,
  ]);

  if (
    !routeMatchesPreference ||
    !state ||
    state.locale !== routeLocale
  ) {
    return (
      <main
        className="min-h-screen"
        aria-busy="true"
      />
    );
  }

  return (
    <IntlBridgeProvider
      locale={routeLocale}
      messages={state.messages}
    >
      {props.children}
    </IntlBridgeProvider>
  );
}

