]);

function friendlyAuthError(code: string | null, t: (key: string) => string) {
    if (!code) return null;

    const safeCode = KNOWN_AUTH_ERROR_CODES.has(code)
        ? code
        : "Default";

    return t(`errors.${safeCode}`);
}

