function deepMerge<T extends Record<string, any>, U extends Record<string, any>>(target: T, source: U): T & U {
    const out: Record<string, any> = { ...target };

    for (const [k, v] of Object.entries(source)) {
        if (isObject(v) && isObject(out[k])) {
