import { tag } from "@/lib/practice/generator/shared/i18n";

export function t(key?: string | null) {
    return key ? tag(key) : "";
}

export function resolveHelp(base: string) {
    const out: Record<string, string> = {};

    const concept = tag(`${base}.help.concept`);
    const hint1 = tag(`${base}.help.hint_1`);
    const hint2 = tag(`${base}.help.hint_2`);

    if (concept !== `${base}.help.concept`) out.concept = concept;
    if (hint1 !== `${base}.help.hint_1`) out.hint_1 = hint1;
    if (hint2 !== `${base}.help.hint_2`) out.hint_2 = hint2;

    return Object.keys(out).length ? out : undefined;
}

export function resolveOptionsByIds(base: string, ids: string[]) {
    return ids.map((id) => ({
        id,
        text: tag(`${base}.options.${id}`),
    }));
}

export function resolveTokensByIds(base: string, ids: string[]) {
    return ids.map((id) => ({
        id,
        text: tag(`${base}.tokens.${id}`),
    }));
}

export function resolveChoicesByCount(base: string, count: number) {
    return Array.from({ length: count }, (_, i) => tag(`${base}.choices.${i}`));
}

import {pickName, safeInt} from "@/lib/practice/generator/engines/python/_shared";



export function tag(key: string) {
    return `@:${key}`;
}

export function getDeep(obj: any, path: string) {
    return String(path)
        .split(".")
        .filter(Boolean)
        .reduce((acc: any, part) => (acc == null ? undefined : acc[part]), obj);
}

export function i18nText(args: any, path: string, fallback: string) {
    const v = getDeep(args?.ctx?.meta?.i18n, path);
    return typeof v === "string" && v.trim() ? v : fallback;
}

export function fillTemplate(template: string, vars: Record<string, string | number>) {
    return template.replace(/\{(\w+)\}/g, (_, key) => String(vars[key] ?? ""));
}

export function pyFStringPrint(template: string) {
    return `print(f${JSON.stringify(template)})\n`;
}

export  function terminalFenceI18n(args: any, stdin: string, stdout: string) {
    const inputLabel = i18nText(args, "common.terminalInputLabel", "input");
    const outputLabel = i18nText(args, "common.terminalOutputLabel", "output");

    return [
        "~~~terminal",
        `$ ${inputLabel}`,
        stdin.trimEnd(),
        "",
        `$ ${outputLabel}`,
        stdout.trimEnd(),
        "~~~",
    ].join("\n");
}

import { describe, expect, it } from "vitest";

import {
  PROFILE_AVATAR_MAX_BYTES,
  profileAvatarFileError,
} from "./profileAvatar";

describe("profileAvatarFileError", () => {
  it("accepts supported images within the limit", () => {
    expect(
      profileAvatarFileError({ type: "image/png", size: 1024 }),
    ).toBeNull();
  });

  it("rejects unsupported image formats", () => {
    expect(
      profileAvatarFileError({ type: "image/svg+xml", size: 1024 }),
    ).toBe("Choose a JPEG, PNG, or WebP image.");
  });

  it("rejects images larger than four megabytes", () => {
    expect(
      profileAvatarFileError({
        type: "image/jpeg",
        size: PROFILE_AVATAR_MAX_BYTES + 1,
      }),
    ).toBe("Profile images must be 4 MB or smaller.");
  });
});

export const PROFILE_AVATAR_MAX_BYTES = 4 * 1024 * 1024;

export const PROFILE_AVATAR_ACCEPT = "image/jpeg,image/png,image/webp";

const PROFILE_AVATAR_TYPES = new Set([
  "image/jpeg",
  "image/png",
  "image/webp",
]);

export type ProfileAvatarFileLike = {
  type: string;
  size: number;
};

export function profileAvatarFileError(file: ProfileAvatarFileLike) {
  if (!PROFILE_AVATAR_TYPES.has(file.type)) {
    return "Choose a JPEG, PNG, or WebP image.";
  }

  if (file.size <= 0) {
    return "The selected image is empty.";
  }

  if (file.size > PROFILE_AVATAR_MAX_BYTES) {
    return "Profile images must be 4 MB or smaller.";
  }

  return null;
}

import { describe, expect, it } from "vitest";

import { resolveProfileNavigation } from "./profileNavigation";

function itemIds(role: "student" | "teacher" | "admin") {
  return resolveProfileNavigation(role).flatMap((section) =>
    section.items.map((item) => item.id),
  );
}

describe("resolveProfileNavigation", () => {
  it("gives every workspace destination a presentation icon", () => {
    for (const role of ["student", "teacher", "admin"] as const) {
      for (const section of resolveProfileNavigation(role)) {
        for (const item of section.items) {
          expect(item.icon, `${role}:${section.id}:${item.id}`).toBeTruthy();
        }
      }
    }
  });

  it("keeps student learning and billing together without management tools", () => {
    expect(resolveProfileNavigation("student").map((section) => section.id)).toEqual([
      "learning",
      "subscription",
    ]);
    expect(itemIds("student")).toEqual([
      "assigned-courses",
      "student-tutoring",
      "achievements",
      "billing",
    ]);
  });

  it("gives teachers their own teaching subset without billing or admin tools", () => {
    expect(resolveProfileNavigation("teacher").map((section) => section.id)).toEqual([
      "learning",
      "teaching",
    ]);
    expect(itemIds("teacher")).toContain("course-assignments");
    expect(itemIds("teacher")).toContain("student-groups");
    expect(itemIds("teacher")).not.toContain("billing");
    expect(itemIds("teacher")).not.toContain("admin-dashboard");
  });

  it("adds platform administration only for admins", () => {
    expect(resolveProfileNavigation("admin").map((section) => section.id)).toEqual([
      "learning",
      "teaching",
      "administration",
    ]);
    expect(itemIds("admin")).toContain("admin-dashboard");
    expect(itemIds("admin")).toContain("public-challenges");
    expect(itemIds("admin")).not.toContain("billing");
  });
});

